<?php
namespace App\Filament\Resources;
use App\Models\RequestMessage; use Filament\Forms; use Filament\Forms\Form; use Filament\Resources\Resource; use Filament\Tables; use Filament\Tables\Table;
class RequestMessageResource extends Resource { protected static ?string $model=RequestMessage::class; protected static ?string $navigationGroup='Requests'; protected static ?string $navigationIcon='heroicon-o-chat-bubble-left-right'; public static function canViewAny():bool{return auth()->user()?->can('requests.view')??false;} public static function form(Form $form):Form{return $form->schema([Forms\Components\Select::make('service_request_id')->relationship('request','reference')->required(),Forms\Components\Textarea::make('body')->required(),Forms\Components\Select::make('audience')->options(['customer'=>'Customer visible','internal'=>'Internal only'])->required(),Forms\Components\Toggle::make('customer_visible'),Forms\Components\Select::make('recipient_id')->relationship('recipient','name'),Forms\Components\FileUpload::make('attachment_path')->disk('local')->directory('message-attachments')->preserveFilenames(false)]);} public static function table(Table $table):Table{return $table->defaultSort('created_at','desc')->columns([Tables\Columns\TextColumn::make('request.reference')->searchable(),Tables\Columns\TextColumn::make('author.name'),Tables\Columns\TextColumn::make('body')->limit(60),Tables\Columns\BadgeColumn::make('audience'),Tables\Columns\TextColumn::make('created_at')->dateTime()])->filters([Tables\Filters\SelectFilter::make('audience')->options(['customer'=>'Customer','internal'=>'Internal'])])->actions([Tables\Actions\EditAction::make()]);} public static function getPages():array{return ['index'=>Pages\ListRequestMessages::route('/'),'create'=>Pages\CreateRequestMessage::route('/create'),'view'=>Pages\ViewRequestMessage::route('/{record}'),'edit'=>Pages\EditRequestMessage::route('/{record}/edit')];} }
